INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (356679, 14613, 'The Economic Times', 'en', 'Tupac mystery finally takes the stand', 'https://economictimes.indiatimes.com/news/international/global-trends/three-decades-after-the-gunfire-rapper-tupacs-murder-gets-its-day-in-court/articleshow/133286568.cms', 'Las Vegas: Opening statements are set to begin Monday in the trial of a man accused of orchestrating the killing of Tupac Shakur, kicking off weeks of testimony that will revisit what happened on a Las Vegas nearly 30 years ago.Duane "Keffe D" Davis, 63, is charged with murder with a deadly weapon with the intent to promote, further or assist a criminal gang in the rapper''s death. He pleaded not guilty, but if convicted, faces life in prison.The long-unsolved drive-by shooting gripped the hip-hop community, partly because no one was charged until Davis was indicted in 2023.Shakur remains a cul', '', '2026-08-17T04:22:29+00:00', '2026-08-17T05:39:52.603914'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
