INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329392, 14638, 'The Guardian', 'en', 'Benjamin Netanyahu describes UK as ‘first Islamic republic to get a nuclear weapon’', 'https://www.theguardian.com/world/2026/aug/14/benjamin-netanyahu-describes-uk-first-islamic-republic-to-get-nuclear-weapon', 'Israeli PM criticised by political rival for attacking an international ally and overseeing ‘horrific diplomatic failure’ The Israeli prime minister, Benjamin Netanyahu, called the UK “the Islamic republic of Britain” in a podcast interview, where he also described the country as the “first Islamic republic to get a nuclear weapon”. His comments, made during an interview for Israel’s army radio, played into a common far-right Islamophobic trope about Britain’s small Muslim population. Continue reading...', 'https://i.guim.co.uk/img/media/591f91a5b5ea545e21d01705a2e603e5af74b717/1331_263_3399_2719/master/3399.jpg?width=140&quality=85&auto=format&fit=max&s=845b7bcb4017ae2e9a9ce0ed12ead242', '2026-08-14T12:00:42+00:00', '2026-08-14T14:58:19.706132'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
