INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329534, 14642, 'France 24', 'en', 'West Bank: Palestinians families trapped in home', 'https://www.france24.com/en/west-bank-palestinians-families-trapped-in-home', 'Israeli settlers are carrying out a campaign of violence and intimidation against the Palestinian village of Qusra in the occupied West Bank, where families have had their electricity and water supplies cut off, in what residents say is an attempt to force them from their homes. France 24 Senior Reporter Catherine Norris Trent recalls reporting from Qusra in 2023, when villagers told her that Israeli settlers were attacking them, preventing them from accessing their land and threatening them with violence if they tried to harvest their olives. The attacks came amid a sharp increase in settler ', 'https://s.france24.com/media/display/10f6cfac-97d3-11f1-b5e1-005056a97e36/w:1024/p:16x9/EN-20260814-130345-130831-CS.jpg', '2026-08-14T11:33:16+00:00', '2026-08-14T14:58:37.168827'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329546, 14642, 'France 24', 'en', 'Israel sends troops to West Bank homes besieged by settlers', 'https://www.france24.com/en/israel-sends-troops-to-west-bank-homes-besied-by-settles', 'Israeli settlers are conducting a campaign of violence and intimidation against the Palestinian village of Qusra in the occupied West Bank. Families have had their electricity and water supplies cut off in what residents say is an attempt to force them from their homes. The IDF has nominally intervened and condemned the violence, but has failed to deter the settlers, who Palestinians say have long benefitted from soldiers turning a blind eye to such attacks. Meanwhile, Washington has sharply condemned the settlers’ actions. Antonia Kerrigan tells us more.', 'https://s.france24.com/media/display/5898b8a8-97b9-11f1-917e-005056a97e36/w:1024/p:16x9/EN-20260814-090117-090304-CS.jpg', '2026-08-14T08:59:38+00:00', '2026-08-14T14:58:37.342846'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
