INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329539, 14645, 'France 24', 'en', 'Earthquake in Colombia: Nearly 300 people trapped in rubbles', 'https://www.france24.com/en/earthquake-in-colombia-nearly-300-people-trapped-in-rubbles', 'In Colombia, hopes are fading of finding survivors after Monday’s powerful earthquake. Rescue teams are now turning their focus to recovering bodies, but families are still holding out hope of finding their loved ones alive beneath the rubble. Many have taken matters into their own hands, as our reporters found when they visited Cali, a city near the quake’s epicentre.', 'https://s.france24.com/media/display/b6f11ef8-97c9-11f1-9ee4-005056bf30b7/w:1024/p:16x9/EN-20260814-101121-101312-CS.jpg', '2026-08-14T10:30:32+00:00', '2026-08-14T14:58:37.241289'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
