INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (333469, 14645, 'France 24', 'en', 'Race to free trapped quake survivor offers hope in Colombia', 'https://www.france24.com/en/americas/20260814-race-to-free-trapped-survivor-offers-hope-in-colombia-earthquake-zone', 'Rescue workers rushed to free a survivor Friday in Colombia amid the rubble left by a powerful earthquake nearly four days earlier that killed at least 285 people and injured 4,000. Some 400 people were still missing and tens of thousands of homes were ​damaged, leaving many Colombians sleeping in shelters or outside.', 'https://s.france24.com/media/display/428de082-97fb-11f1-b1f2-005056bf30b7/w:1024/p:16x9/AP26223819165884.jpg', '2026-08-14T16:49:37+00:00', '2026-08-14T17:16:16.048897'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
